  auto PANEL_ID__ = PANEL_ID ? _fbb.CreateString(PANEL_ID) : 0;
  auto GLTF_MATERIAL_NAME__ = GLTF_MATERIAL_NAME ? _fbb.CreateString(GLTF_MATERIAL_NAME) : 0;
